import React from "react";

const SlotCard = ({ slot }) => {
  const isOccupied = slot.status === "occupied";

  return (
    <div className={`slot-card ${isOccupied ? "occupied" : "vacant"}`}>
      <div className="slot-top">
        <div className="slot-number">Slot {slot.slot}</div>
        <div className="slot-badge">{isOccupied ? "Occupied" : "Vacant"}</div>
      </div>

      <div className="slot-body">
        <div className="slot-icon">{isOccupied ? "🚗" : "🅿️"}</div>
        <div className="slot-info">
          <div className="plate">{slot.plate || "-"}</div>
          <div className="time">{slot.time ? new Date(slot.time).toLocaleTimeString() : "-"}</div>
        </div>
      </div>
    </div>
  );
};

export default SlotCard;
